<script setup>
import {computed,ref,toRef} from 'vue'
import {Button,Badge,FormControl} from '@relay/ui'
import RelayTable from './RelayTable.vue'
import RelayForm from './RelayForm.vue'
import {arrayPageSource} from './search'
const props=defineProps({view:String,threads:Array,contacts:Array,items:Array});const emit=defineEmits(['open','filter'])
const query=ref(''),category=ref('All'),editing=ref(false),error=ref(''),draft=ref({}),items=toRef(props,'items')
const contactsSource=arrayPageSource(()=>props.contacts.filter(c=>category.value==='All'||c.type===category.value),c=>[c.name,c.company,c.record,c.type,...c.channels].join(' '))
const draftsSource=arrayPageSource(()=>props.items.filter(i=>i.view===props.view),i=>[i.title,i.message,i.channel].join(' '))
const recentSource=arrayPageSource(()=>props.threads,t=>t.name+' '+t.team)
const metrics=computed(()=>[{label:'Open',value:props.threads.filter(t=>t.status==='Open').length,filter:'All'},{label:'Unread',value:props.threads.filter(t=>t.unread>0).length,filter:'Unread'},{label:'Important',value:props.threads.filter(t=>t.important).length,filter:'Important'}])
const fields=computed(()=>props.view==='Canned replies'?[{name:'title',label:'Title',type:'Data',required:true},{name:'channels',label:'Channels',type:'MultiSelect',options:['WhatsApp','Telegram','Email'],required:true},{name:'message',label:'Message',type:'Small Text',required:true,wide:true}]:[{name:'title',label:'Campaign name',type:'Data',required:true},{name:'channel',label:'Channel',type:'Select',options:['WhatsApp','Telegram','Email'],required:true},{name:'recipients',label:'Contacts',type:'MultiSelect',options:props.contacts.filter(c=>c.channels.includes(draft.value.channel)).map(c=>({label:c.name,value:c.id})),required:true,wide:true}])
const contactColumns=[{key:'name',label:'Contact'},{key:'type',label:'Business type'},{key:'company',label:'Company'},{key:'channels',label:'Channels',minWidth:180},{key:'action',label:'',minWidth:140}]
const draftColumns=[{key:'title',label:'Name'},{key:'details',label:'Details',minWidth:260},{key:'status',label:'Status'}]
function create(){draft.value={title:'',channel:'WhatsApp',channels:[],recipients:[],message:''};error.value='';editing.value=true}
function save(){error.value='';if(props.view==='Campaigns'&&(draft.value.recipients||[]).some(id=>!props.contacts.find(c=>c.id===id)?.channels.includes(draft.value.channel))){error.value='Select contacts available on this channel.';return};items.value.push({...draft.value,id:'RELAY-DRAFT-'+String(items.value.length+1).padStart(6,'0'),view:props.view});editing.value=false}
</script>
<template><div class="page-body"><template v-if="view==='Dashboard'"><h2 class="text-xl font-semibold mb-6">My workspace</h2><div class="grid grid-cols-1 sm:grid-cols-3 gap-4 mb-8"><button v-for="m in metrics" :key="m.label" class="border rounded-lg p-5 text-left" @click="emit('filter',m.filter)"><span class="block text-sm text-ink-gray-5 mb-3">{{m.label}}</span><strong class="text-2xl">{{m.value}}</strong></button></div><h3 class="text-base font-medium mb-3">Recent conversations</h3><RelayTable :fetch-page="recentSource" :columns="[{key:'name',label:'Contact'},{key:'channel',label:'Channel'},{key:'team',label:'Team'},{key:'action',label:''}]" label="Recent conversations"><template #channel="{item}"><Badge :label="item.channel"/></template><template #action="{item}"><Button label="Open" @click="emit('open',item.id)"/></template></RelayTable></template><template v-else-if="view==='Contacts'"><div class="flex flex-wrap gap-3 mb-5"><FormControl v-model="query" placeholder="Search contacts" aria-label="Search contacts" type="search"/><FormControl v-model="category" type="select" :options="['All','Customer','Supplier','Employee']" label="Business type"/></div><RelayTable :fetch-page="contactsSource" :columns="contactColumns" :query="query" :revision="category" label="Contacts"><template #name="{item}"><strong>{{item.name}}</strong><p class="text-xs text-ink-gray-5">{{item.record}}</p></template><template #channels="{item}"><span v-for="ch in item.channels" :key="ch" class="channel-label" :data-channel="ch">{{ch}}</span></template><template #action="{item}"><Button label="Conversation" @click="emit('open',threads.find(t=>t.contact===item.id)?.id)"/></template></RelayTable></template><template v-else><div class="flex items-center justify-between mb-6"><h2 class="text-xl font-semibold">{{view}}</h2><Button v-if="!editing" :label="view==='Campaigns'?'New campaign':'New reply'" icon-left="plus" variant="solid" @click="create"/></div><section v-if="editing" class="max-w-3xl border border-outline-gray-2 rounded-lg p-6"><RelayForm v-model="draft" :fields="fields" :error="error" label="Save draft" @submit="save"><template #actions><Button label="Cancel" @click="editing=false"/></template></RelayForm></section><template v-else><div class="max-w-sm mb-4"><FormControl v-model="query" type="search" :placeholder="'Search '+view.toLowerCase()" :aria-label="'Search '+view.toLowerCase()"/></div><RelayTable :fetch-page="draftsSource" :columns="draftColumns" :query="query" :revision="items.length" :label="view"><template #details="{item}">{{item.message||`${item.channel} · ${item.recipients.length} contacts`}}</template><template #status><Badge label="Session draft"/></template></RelayTable></template></template></div></template>
